import{_ as n,l as s,o as e,c as o,v as t,p as h,x as i,d as l,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const H=JSON.parse('{"title":"MinHash 与 LSH","description":"","frontmatter":{"title":"MinHash 与 LSH","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/minhash-lsh.md","filePath":"cs/minhash-lsh.md","lastUpdated":1789023840000}'),p={name:"cs/minhash-lsh.md"};function m(_,a,S,u,A,B){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="minhash-与-lsh" tabindex="-1">MinHash 与 LSH <a class="header-anchor" href="#minhash-与-lsh" aria-label="Permalink to &quot;MinHash 与 LSH&quot;">​</a></h1><div class="epigraph"><p>每个哈希取集合里最小的像；两集合签名相等的概率等于 Jaccard。多组签名做成桶，相似的对才进同一桶。</p><footer>—— 据 Broder, On the Resemblance and Containment of Documents, SEQS 1997；Indyk and Motwani, Approximate Nearest Neighbors: Towards Removing the Curse of Dimensionality, STOC 1998 整理</footer></div><p><a href="/cs/quotient-filter">上一课</a> 问成员。<a href="/cs/count-min-sketch">Count-Min</a> 问频次。近重复文档、相似集合要 Jaccard \\(J(A,B)=|A\\cap B|/|A\\cup B|\\)，穷举对是平方。<a href="/cs/universal-hashing">通用散列</a> 给独立排列的代理。本课不扫商簇。缺口是 MinHash 签名 + LSH 分桶。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>精确 Jaccard 要交并。MinHash：随机排列 \\(\\pi\\)，签名 \\(\\min\\pi(A)\\)。\\(\\Pr[\\min\\pi(A)=\\min\\pi(B)]=J(A,B)\\)。\\(k\\) 个独立哈希得 \\(k\\) 维签名，用相等比例估 \\(J\\)。LSH：把签名切成 \\(b\\) 段，每段哈希进桶；至少一段完全相同则成候选，再精确比。缺口是<strong>用碰撞概率对准相似度阈值</strong>，避开高维 k-d 树失效。</p><p><span class="marginnote">Broder 1997 近似文档。Indyk–Motwani STOC 1998 提出 LSH 框架。本课不把 E2LSH 全部度量抄成词条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现常用 \\(k\\) 个哈希的最小，或一个哈希的 \\(k\\) 个最小（bottom-\\(k\\)，分析略不同）。LSH 参数 \\((b,r)\\)：\\(k=br\\)，使 \\(J\\) 高的对期望进桶、\\(J\\) 低的少进。候选再算真 Jaccard 或抽查。</p>',8)),(e(),h(c,null,{default:i(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E9%9B%86%E5%90%88%20A%22%5D%20--%3E%20MH%5B%22k%20%E4%B8%AA%20min%20%E5%93%88%E5%B8%8C%22%5D%0A%20%20MH%20--%3E%20BAND%5B%22%E5%88%86%E6%88%90%20b%20%E6%AE%B5%22%5D%0A%20%20BAND%20--%3E%20BUCK%5B%22%E6%AE%B5%E5%93%88%E5%B8%8C%E5%85%A5%E6%A1%B6%22%5D%0A%20%20BUCK%20--%3E%20CAND%5B%22%E5%80%99%E9%80%89%E5%AF%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 HLL：HLL 是单集合基数；MinHash 是两集合相似。与 k-d：<a href="/cs/kd-tree">k-d 树</a> 正交范围，LSH 对角度/Jaccard/欧氏有不同族。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>独立性不够则估计偏。对抗哈希同样破坏概率合同。不要把 LSH 写成深度学习检索课的唯一内容——本课是概率数据结构。</p><p>流上固定大小样本下一课蓄水池，问题从相似转到「均匀抽 \\(k\\) 个」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明所有度量的 \\((r,cr,p1,p2)\\) 定义全文。欧氏 LSH 用 p-stable，点名。精确近邻在低维仍可用树。</p><p>后课默认：Jaccard 近似用 MinHash；分桶检索用 LSH。流上均匀样本用蓄水池。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MinHash：\\(\\Pr(\\text{签名相等})=Jaccard\\)。</li><li>LSH：分段入桶放大近对碰撞。</li><li>下一课在未知长度的流上均匀抽样。</li><li>出处：Broder, 1997；Indyk and Motwani, <em>STOC</em>, 1998。</li></ul>',9))])}const f=n(p,[["render",m]]);export{H as __pageData,f as default};
